namespace Scheduling;

/// <summary>
/// Coordinates focused scheduling services while preserving the scheduling facade.
/// </summary>
public sealed class ScheduleManager
{
    private readonly SchedulePlacementService _placementService;
    private readonly ScheduleMatchingService _matchingService = new();
    private readonly ScheduleConflictService _conflictService = new();
    private readonly ScheduleNotificationService _notificationService;

    public ScheduleManager()
    {
        _placementService = new SchedulePlacementService();
        _notificationService = new ScheduleNotificationService(_placementService);
    }

    public string Place(Job job, Resource resource) =>
        _placementService.Place(job, resource);

    public bool Unplace(Job job) =>
        _placementService.Unplace(job);

    public int PlacementCount => _placementService.PlacementCount;

    public Resource? Match(Job job, IReadOnlyList<Resource> resources) =>
        _matchingService.Match(job, resources);

    public void RecordDemand(Job job) =>
        _matchingService.RecordDemand(job);

    public int DemandFor(string skill) =>
        _matchingService.DemandFor(skill);

    public bool HasConflict(Slot candidate) =>
        _conflictService.HasConflict(candidate);

    public bool Book(Slot candidate) =>
        _conflictService.Book(candidate);

    public int Overlaps(Slot candidate) =>
        _conflictService.Overlaps(candidate);

    public bool Notify(Job job) =>
        _notificationService.Notify(job);

    public string Reschedule(Job job, Resource resource) =>
        _placementService.Reschedule(job, resource);

    public int ResolveConflicts(Slot candidate) =>
        _conflictService.ResolveConflicts(candidate);

    public string Escalate(Job job) =>
        _notificationService.Escalate(job);

    public int NotifiedCount => _notificationService.NotifiedCount;
}

internal sealed class SchedulePlacementService
{
    private readonly Dictionary<string, string> _placements = new(StringComparer.Ordinal);

    public string Place(Job job, Resource resource)
    {
        if (string.IsNullOrEmpty(job.Id))
            return "no id";
        if (_placements.ContainsKey(job.Id))
            return "already placed";
        if (job.Duration <= TimeSpan.Zero)
            return "bad duration";
        if (resource.Calendar.Count > 50)
            return "resource full";

        _placements[job.Id] = resource.Name;
        return resource.Name;
    }

    public bool Unplace(Job job)
    {
        if (string.IsNullOrEmpty(job.Id))
            return false;

        return _placements.Remove(job.Id);
    }

    public bool Contains(string jobId) => _placements.ContainsKey(jobId);

    public int PlacementCount => _placements.Count;

    public string Reschedule(Job job, Resource resource)
    {
        if (string.IsNullOrEmpty(job.Id))
            return "no id";
        if (!_placements.ContainsKey(job.Id))
            return "not placed";
        if (resource.Calendar.Count > 50)
            return "target full";
        if (job.Duration <= TimeSpan.Zero)
            return "bad duration";
        if (resource.Skills.Count == 0)
            return "no skills";
        if (!string.IsNullOrEmpty(job.RequiredSkill) && !resource.Skills.Contains(job.RequiredSkill))
            return "skill mismatch";

        _placements[job.Id] = resource.Name;
        return job.Priority > 7 ? $"{resource.Name}:priority" : resource.Name;
    }
}

internal sealed class ScheduleMatchingService
{
    private readonly Dictionary<string, int> _skillDemand = new(StringComparer.OrdinalIgnoreCase);

    public Resource? Match(Job job, IReadOnlyList<Resource> resources)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill))
            return null;

        Resource? best = null;
        foreach (var resource in resources)
        {
            if (!resource.Skills.Contains(job.RequiredSkill))
                continue;
            if (best == null || resource.Calendar.Count < best.Calendar.Count)
                best = resource;
        }

        return best;
    }

    public void RecordDemand(Job job)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill))
            return;

        var current = _skillDemand.TryGetValue(job.RequiredSkill, out var count) ? count : 0;
        _skillDemand[job.RequiredSkill] = current + (job.Priority > 5 ? 2 : 1);
    }

    public int DemandFor(string skill)
    {
        if (string.IsNullOrEmpty(skill))
            return 0;

        return _skillDemand.TryGetValue(skill, out var count) ? count : 0;
    }
}

internal sealed class ScheduleConflictService
{
    private readonly List<Slot> _booked = new();

    public bool HasConflict(Slot candidate)
    {
        if (!IsValid(candidate))
            return true;

        foreach (var booked in _booked)
        {
            if (Overlaps(candidate, booked))
                return true;
        }

        return false;
    }

    public bool Book(Slot candidate)
    {
        if (!IsValid(candidate) || HasConflict(candidate))
            return false;
        if (candidate.Start.Hour < 6 || candidate.End.Hour > 22)
            return false;

        _booked.Add(candidate);
        return true;
    }

    public int Overlaps(Slot candidate)
    {
        var count = 0;
        foreach (var booked in _booked)
        {
            if (Overlaps(candidate, booked))
                count++;
        }

        return count;
    }

    public int ResolveConflicts(Slot candidate)
    {
        if (!IsValid(candidate))
            return -1;

        var resolved = 0;
        var keep = new List<Slot>();
        foreach (var booked in _booked)
        {
            if (!Overlaps(candidate, booked))
            {
                keep.Add(booked);
            }
            else if (booked.End - booked.Start < candidate.End - candidate.Start)
            {
                resolved++;
            }
            else if (booked.Start < candidate.Start)
            {
                keep.Add(booked);
            }
            else
            {
                resolved++;
            }
        }

        if (resolved > 0)
        {
            _booked.Clear();
            _booked.AddRange(keep);
        }

        return resolved;
    }

    private static bool IsValid(Slot slot) => slot.End > slot.Start;

    private static bool Overlaps(Slot first, Slot second) =>
        first.Start < second.End && second.Start < first.End;
}

internal sealed class ScheduleNotificationService
{
    private readonly SchedulePlacementService _placements;
    private readonly HashSet<string> _notified = new(StringComparer.Ordinal);

    public ScheduleNotificationService(SchedulePlacementService placements)
    {
        _placements = placements;
    }

    public bool Notify(Job job)
    {
        if (string.IsNullOrEmpty(job.Id))
            return false;
        if (_notified.Contains(job.Id) || !_placements.Contains(job.Id))
            return false;
        if (job.Priority <= 0)
            return false;

        _notified.Add(job.Id);
        return true;
    }

    public string Escalate(Job job)
    {
        if (string.IsNullOrEmpty(job.Id))
            return "no id";
        if (!_notified.Contains(job.Id))
            return "not notified";
        if (job.Priority > 9)
            return "exec";
        if (job.Priority > 7)
            return "manager";
        if (job.Priority > 4)
            return "lead";
        if (job.Duration.TotalHours > 24)
            return "long-running";
        if (_notified.Count > 100 && job.Priority > 0)
            return "batch";

        return "none";
    }

    public int NotifiedCount => _notified.Count;
}
